"""Canonical scout's measured spec authoring. All meshing is performed by upstream.

This file is fixture DATA authoring, not the Forge reconstruction engine. Pixel
measurements belong to the recorded reference. Another subject requires its own
observations and spec; replacing only the source image cannot reuse these numbers.
"""
import os,sys,copy,math
from pathlib import Path
from PIL import Image,ImageDraw
r=Path(os.environ['FORGE_REPO']);sys.path.insert(0,str(r/'packages/assets/forge'))
from upstream.engine import Engine,save_json,load_json
