s['preSpecAssessment']=a['preSpecAssessment'];s['qualityContract']=a['qualityContract'];s['targetId']='canonical-scout-upstream'
template=copy.deepcopy(s['componentTree'][1]);mt={m['id']:m for m in s['materials']};scale=1.6/260
components=[];positions={'root':[0,0,0]}
def xyz(x,y,z=0):return [(x-60)*scale,(265-y)*scale,z*scale]
def comp(id,material,pos,dimensions=(1,1,1),primitive='ellipsoid',level='meso',parent='root',descriptor=None,layer='L3',rotation=None):
 c=copy.deepcopy(template);c.update(id=id,name=id,material=material,materialLayers=[material],parent=parent,primitive=primitive,level=level,importance=.9,confidence=.75)
 positions[id]=list(pos);pp=positions.get(parent,[0,0,0]);c['transform']={'position':[pos[k]-pp[k] for k in range(3)],'rotation':rotation or [0,0,0],'scale':list(dimensions)}
 c['dimensions']={'width':dimensions[0],'height':dimensions[1],'depth':dimensions[2],'units':'metre','confidence':.75}
 c['topologyClass']='assembled-solid';c['topologyRationale']='Observed '+id+' volume; '+layer+' geometry generated by pinned upstream from source measurements.'
 c['geometryDescriptor'].update(descriptor or {});c['geometryDescriptor']['uvStrategy']='generated';c['attachment']=None
 c['evidenceRefs']=['img2threejs/observation.json','source/front.png','source/side.png','source/back.png'];c['fidelityTier']='reference-reconstruction';c['primaryLayer']=layer
 c['localFeatures']=[{'id':id+'-outline','description':'Observed outline and surface identity for '+id,'evidenceRefs':c['evidenceRefs']}]
 c['surfaceDetail']['notes']='Source projection is required later. Hidden surfaces are inferred. No retired model texture is reused.'
 c['actionProfile']['collider']['scale']=list(dimensions);c['actionProfile']['destruction']['debrisMaterial']=material;c['actionProfile']['destruction']['fractureGroup']=id
 if parent:
  local=c['transform']['position'];c['attachment']={'parentSocket':parent+'-to-'+id,'localStart':local,'localEnd':[local[0],local[1]+.01,local[2]],'contactType':'rigid-weld' if layer=='L3' else 'soft-attach','baseRadius':.01,'endRadius':.005,'embedDepth':.01,'gapTolerance':.01,'evidenceRefs':c['evidenceRefs']}
  par=next((q for q in components if q['id']==parent),None)
  if par:par['actionProfile']['sockets'].append({'id':parent+'-to-'+id,'localPosition':local,'localRotation':[0,0,0],'purpose':'observed-part-attachment'})
 components.append(c);return c
comp('root','hidden',[0,0,0],(.0001,.0001,.0001),'box','macro',None)
comp('pelvis','skin',xyz(60,139),(.23,.15,.14),level='macro',layer='L0')
comp('abdomen','shirt',xyz(60,123),(.21,.19,.15),level='macro',parent='pelvis',layer='L0')
comp('chest','shirt',xyz(60,93),(.24,.27,.16),level='macro',parent='abdomen',layer='L0')
comp('neck','skin',xyz(60,60),(.08,.09,.085),parent='chest',layer='L0')
